const ruler = (r, phaseName) => agent(`${RULES}\nRole: ruler (Engineer), rules.md section (e). Builder branch origin/${r.branch} stopped with: ${r.stop_reason}\nSpec: ${SPEC}. Rulebook: docs/northstar/plans/2026-10-07-visible-game-rulebook.md (its "Decision procedure" word for word; lane E rows are TD-VG-E-<n>, next free number from the ledger docs/northstar/plans/push_ledger_2026-09-22.md above every TD-VG-E number named in the ledger or the spec). Branch push/vg-e1screens-rulings (suffix vg-e1screens-rulings; continue it from origin if it exists: worktree add ~/Projects/om-push/wt/vg-e1screens-rulings origin/push/vg-e1screens-rulings then git checkout -B push/vg-e1screens-rulings, else from ${BASE}). If every condition of the procedure holds: edit only the one test file named, run it alone and its positive control, append the ledger row, push, report ruled true with row and branch. Else report ruled false and brief (under one page: test id and failing line, the builder's claim, the spec and bible lines that bear on it, two or three options with what each changes). A threshold, a window, a tolerance or a Westley-owned number is never ruled: ruled false. A test-defect that encodes the answer to a GAP (${GAP_DEFS.map(g => g.n).join(', ')}) is ruled false.`, { label: `rule:${r.branch}`, phase: phaseName, schema: RULING, agentType: 'engineer', model: 'sonnet' })
const withRuling = async (mk, phaseName) => {
  let r = await mk('')
  if (r && !r.ok && /^test-defect:/.test(r.stop_reason || '')) {
    const v = await ruler(r, phaseName)
    if (v && v.ruled && v.branch) { r = await mk(`, origin/${v.branch} (ruling ${v.row})`); r = { ...r, ruling: v } } else { r = { ...r, ruling: v } }
  }
  return r
}
