const mkBW = (extra) => done('build:w') || agent(`${RULES}\nRole: Doer (rules.md section (a)) for E1w of ${SPEC}.\n${IFACE}\n${RULED}\nBranch push/vg-e1w, suffix vg-e1w, from ${BASE} (ruling g5: it stacks on the latest tactical_view.gd branch in the chain; the base must already contain the work of the queued tactical_view.gd owners the Preflight listed, attached or through args.baseRef; if it does not, stop with stop_reason "order: <the piece> not in the base"); ${BUILD_COMMON([tw.branch, bm.branch, bn.branch], extra)}. Edit ONLY ${VIEW} ${EXTRA_FILES.length ? 'and ' + EXTRA_FILES.join(', ') : ''}. Build exactly the ${VIEW} part of the INTERFACE block under the rulings above: wiring and nothing else (no new layer logic, no refactoring, no change to a line the wiring does not need). Re-find every site by name (the line numbers in the script header are from 01c2e752 and have moved). Run ${T_W} until green, then tests/test_vg_e_e1p.gd, tests/test_tactical_view.gd, tests/test_vg_a_events_feed.gd and the known-red files (scripts/specfactory/gd_tests_known_red.txt) and compare the sorted red list with the Preflight baseline: any new red is yours to fix or a stop. Run ${PLAY} once under xvfb-run -a timeout 900 with OM_QA_RENDERER=vulkan on your tree and report pass/fail and the decisive line. Pre-gate with ${ALL_TESTS}. Push the branch; report.`, { label: 'build:E1w', phase: 'Build', schema: REPORT, agentType: 'doer', model: 'sonnet' })
const bw = await withRuling(mkBW, 'Build')
out = { ...out, builds: { m: bm, n: bn, w: bw } }
if (!(bw && bw.ok)) return { ...out, stopped: 'build-w' }

phase('Check')
const checks = await parallel([
  checkOne(tm, 'chk-e1m-tests', `Only ${T_M} and its .uid (and ledger rows) changed against the merge base; on origin/main merged with this branch (never stash; a second detached worktree) [CONTROL] is green and the other groups are red for the stated reason (${TICKER} missing): re-run and paste each group's first failing line; the header quotes R-235-01 to R-235-04 and R-104-01 word for word against the bible; every case names the sentence it proves; the [FEED] group has the non-strongpoint negative control and the first-frame rule; a build that emits on the wrong id would fail a named case (say which).`),
  checkOne(tn, 'chk-e1n-tests', `Only ${T_N} and its .uid (and ledger rows) changed; [CONTROL] green on origin/main, the other groups red for the stated reason (${MARKERS} missing); [STRONGPOINT] contains the stale-list negative control (the strongpoints list says enemy, the structures row says own); [KINDS] asserts that no stub kind is ever produced; quotes are word for word; no number nobody gave (every size or colour comes from a ruling or a named draft).`),
  checkOne(tw, 'chk-e1w-tests', `Only ${T_W}, ${PLAY} and .uid files changed; [CONTROL] green on origin/main and the view-instantiation premise reproduced; the other groups red for the stated reason (no TickerBeats or MapMarkers node, no map_markers key): re-run and paste the first failing line of each; run ${PLAY} once under xvfb-run (OM_QA_RENDERER=vulkan, timeout 900) on origin/main and paste its decisive failing line; the play asserts the INVENTORY of the interface block with each assert naming its rule, and drives the event per the GAP 8 ruling; the Vulkan banner naming Forward+ appears in its game log (quote it).`),
  checkOne(bm, 'chk-e1m-build', `JOIN. The diff versus its merge base touches only ${TICKER}, its .uid, ${FEED} and the ledger row; ${T_M} green (PASS/FAIL counts) and red again with ${TICKER} reverted; the node name is TickerBeats and the signal is named beat(kind, text) exactly as events_feed.gd:94-96 connects it; emit_beat returns false and emits nothing for shipment and forward_base; the strongpoint beats follow the GAP 2 ruling; no event outside KINDS; DRAFT-e1m-beat-text is in the ledger and marked in the file; no wall clock, no randomness; the diff of ${FEED} is the three-line skip of GAP 2 (b) and nothing else, and ${FEED} is in the diff only for that; tests/test_vg_a_events_feed.gd green; the four stub kinds are labelled STUB in the file header.`),
  checkOne(bn, 'chk-e1n-build', `JOIN. The diff versus its merge base touches only ${MARKERS}, its .uid and the ledger row; ${T_N} green and red again with the file reverted; set_frame's projection and colours equal StructuresLayer's (quote both sites); markers() rows have exactly the keys {kind, x, y, owner, state}; kinds follow the GAP 6 ruling and nothing else is produced; DRAFT-e1n-marker is in the ledger and marked in the file.`),
  checkOne(bw, 'chk-e1w-build', `JOIN AND REGRESSION. The diff versus origin/main (the branch holds the merged tests and both builds) touches only ${VIEW}, ${TICKER}, ${FEED}, ${MARKERS}, ${T_M}, ${T_N}, ${T_W}, ${PLAY}, the ledger and .uid files; no C file, no pipe; ${FEED} only as merged from the E1m branch (the three-line skip). The ${VIEW} diff is wiring only: PIECES entries, _build_shell lines, the two frame-path calls, qa_state map_markers, the _inventory count; nothing else moved. Run, one at a time: ${ALL_TESTS}, tests/test_vg_e_e1p.gd, tests/test_tactical_view.gd, tests/test_vg_a_events_feed.gd, every other tests/test_vg_*.gd and the files of scripts/specfactory/gd_tests_known_red.txt; compare the sorted red list with the Preflight baseline and list every new red (blocking). Run ${PLAY} once (xvfb-run -a timeout 900, OM_QA_RENDERER=vulkan) and the S-193, S-168 and s218 plays one at a time; report pass or fail and the decisive line of each. WIRED check: from the running view's frame path (not a test call) a structure owner flip of a strongpoint reaches Events.lines(); quote the path.`),
])
out = { ...out, checks }
if ([tm, tn, tw, bm, bn, bw].some((r, i) => !(checks[i] && checks[i].pass))) return { ...out, stopped: 'check' }

phase('Clerk')
const shotPart = ' No REJECT: run the S-235 play on the merged tree (xvfb-run -a, OM_QA_RENDERER=vulkan, timeout 900, tests/qa/desktop/plays/E/S-235.py, one run, the machine otherwise quiet). BEFORE queueing anything confirm the standing Forward+ rule: the play\'s Godot log (GodotGame stdout under its scratch dir) must contain the Vulkan banner line naming Forward+ (quote it); if it does not, the shot is NOT queued: report shots empty and say so. The run id is YYYYMMDD-HHMM-<main sha7 after merge>; copy the png and qa_state json (and every moment the play writes) to docs/northstar/story_reviews/shots/<run id>/ as S-235.png and S-235.state.json. Read the png and write the reviewer line (reviewer sonnet; yes/no/unclear) as honest evidence, one clause each: (1) is there a mark for every strongpoint in view, coloured by owner; (2) is the home base marked; (3) does the ticker name the strongpoint taken or lost; (4) is any other economy beat on the ticker (there must be none); (5) say plainly, as a stub line, that base occupied, fall back to an expansion, expansion founded and weather arrives have no sim source on main, and that economic locations, neutral settlements, expansions, forward works and the weather have no marks. Also state from qa_state the marker counts per kind and the hud.events count. Add a NEW row (story S-235, newest first) to docs/northstar/story_reviews/E.md with the columns of the existing rows, Westley verdict pending, quoting R-235-03; never mark a story Seen and never edit stories.md. The westley folder (ruled g10, 2026-10-14: the S-235 shot queues BEHIND S-191): write the E.md queue row and keep the shot under shots/<run id>/; do NOT copy the png into docs/northstar/story_reviews/westley/ and add no README row now: the copy is HELD until the lane slot is free (the S-191_skel shot has its verdict and the README table holds no lane E row); say in the report that the copy is held, name the png path and the one-line copy recipe for the Dispatcher (png to docs/northstar/story_reviews/westley/E-S235-<what it shows>.png plus its README row), and make no folder edit. If the play is red because no strongpoint beat arrived within the cap, that is a FINDING (Architect round 3): report it with the decisive line, write no E.md row and queue no shot; the play never labels a beatless shot. Name every shot path in the report under shots. If the play is red, report the decisive line; do not edit the play.'
const clerk = await agent(`${RULES}\nRole: landing clerk (Engineer), rules.md section (b). Pieces ${PM}, ${PN}, ${PW} of ${SPEC}. ${RULED}\n${PUSH_MAIN ? 'The push to main at the end IS authorised on a clean gate (the Dispatcher launched this under Westley\'s standing word for clean-gate pushes). Push main only when every GATE REJECT line names a test listed in scripts/specfactory/gd_tests_known_red.txt (the clerk-read file, one exact id plus a row id) or a play listed in scripts/specfactory/lane_plays_known_red.txt (confirm each is red alone on origin/main before relying on it); any other reject, or any unexplained red, means branch only. Never edit those two files except the one case below.' : 'Do NOT push to main: push the branch only and report; the Dispatcher decides.'} Branch push/vg-e1screens-land, suffix vg-e1screens-land, from ${BASE} (STACK RULE: ${STACKED ? 'this landing is stacked on ' + BASE_REFS.join(', ') + '. After git fetch origin run git merge-base --is-ancestor <ref> origin/main for each ref. If EVERY ref is an ancestor (the stack landed), merge origin/main instead of the stack refs and the push to main is allowed under the other rules. If ANY is not, you land NOTHING on main: stop at the branch push/vg-e1screens-land, put "stacked on <refs>, not landed" at the top of the summary, still run the pre-gate, the tests and the shots, and report; the Dispatcher relaunches you alone after the stack lands.' : 'not stacked: normal landing.'}); merge origin/${tm.branch}, origin/${tn.branch}, origin/${tw.branch}, origin/${bm.branch}, origin/${bn.branch}, origin/${bw.branch}${rulingMerge()}, then origin/main if it moved (say so; ledger appends keep both sides). Stage files by name only; delete any untracked .uid that is not beside a new script of this lane before a checkout or merge. Park files (*_park_*) stay OFF the candidate when red (none expected). Build; run ${ALL_TESTS} and the files of the Preflight baseline (PASS/FAIL per file). Pre-gate before the lock (section (b)): ${PREGATE('<worktree>', ALL_TESTS)} must end PRE_GATE verdict OK (the piece list is ONE comma-joined third argument, exactly "${PIECES}"; with more than one id the acceptance and undertest steps WARN and skip: list those WARN lines in the report and run the acceptance files yourself). A reject on lint, footprint, owner row or noise is fixed or reported before the lock, never spent on a full gate. Full gate per section (b), from the worktree, detached with setsid nohup into <TMPDIR>/gate.log, the lock taken first and origin/main fetched and merged inside it (main moves while a clerk waits for the lock): flock ~/Projects/om-push/gate.lock env TMPDIR=$HOME/Projects/om-push/tmp-vg-e1screens MERGE_GATE_SUITE_TIMEOUT=2400 MERGE_GATE_PLAYTHROUGH_TIMEOUT=2400 MERGE_GATE_PLAY_TIMEOUT=900 MERGE_GATE_PIECES=<worktree>/docs/northstar/plans/push/pieces.toml bash -c 'cd <worktree> && git fetch origin && git merge --no-edit origin/main && scripts/specfactory/pre_gate.sh <worktree> origin/main ${PIECES} && scripts/specfactory/merge_gate.sh <worktree> origin/main ${PIECES}' (three positional arguments to each script; the pre-gate above is the cheap early check and pre_gate runs again inside the lock, on the tree after the merge; the script rejects a candidate that lacks the current origin/main, so a forgotten merge costs seconds, not a gate). Poll gate.log for the ^GATE look line with one foreground command under 10 minutes at a time, every 5 minutes at most; then pgrep -f '^bash scripts/specfactory/merge_gate.sh' to confirm no gate for the worktree still runs (never pgrep your own command line). There is no VERDICT line: the verdict is the set of GATE <stage> REJECT lines. Flake rule per section (b). The playthrough stage is the wired check (the markers and the beat are reachable from the running tick through the view). Known-red case: if the lane plays stage rejects only because plays/E/S-235.py passes while listed (it is not listed today), or s218 starts passing (it will not: E1l is not built), report the exact line and make no edit.${shotPart} In the landing commit: flip the rows ${PM}, ${PN}, ${PW} in docs/northstar/plans/push/pieces.toml to attached with the E1w branch tip sha (comment 'landed <sha7>'); in docs/northstar/plans/2026-10-07-visible-game-programme.md flip the lane table row "E settlement and economy" (the row that lists the skeleton and the port): On main: append "S-235 skeleton (E1m ticker, E1n markers, E1w wiring: strongpoint beat and strongpoint/home-base marks only, the other beats and marks are stubs; Westley pending) at <sha7>", Next piece: "Westley's verdict on the S-235 shot"; leave the E1l, E1o, E1p-b and VG-P3 words as they are; write nothing about status anywhere else (rules.md (b): no ROADMAP lane row, no journal line). The ledger rows (TD-VG-E-<n>, DRAFT-e1m-beat-text, DRAFT-e1n-marker, DRAFT-s235-budget if used) are already on the merged branches; check they are present. The four stub rows FU-E1m-beat-base-occupied, FU-E1m-beat-fall-back, FU-E1m-beat-expansion-founded and FU-E1m-beat-weather-arrives are already on main in the ledger: check they are present and add none. Then fetch origin and merge origin/main right before the push (say whether it moved; if it moved re-run the pre-gate, not the full gate, and say so); commit with a normal-prose subject (the subject is the journal) ending with the line Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>; push the branch to origin as push/vg-e1screens-land${PUSH_MAIN ? ', then git push origin HEAD:main when the rule above allows it' : ''}. Else branch only, every GATE REJECT line quoted. Write .wt-done (date, branch, pushed sha) after the push; remove only the merge_gate_before_* directories under your own TMPDIR. Report ok, branch, sha, summary (every GATE REJECT line or "OK per stage"; the pre-gate verdict; the Forward+ banner line; main head; whether the shot went to the westley folder or stayed in the queue), red_ids, parked, shots. tests/test_vg_e_e1n.gd and tests/test_vg_e_e1w.gd run under xvfb-run -a in place of the headless PRE_GATE line (FU-E1n-pregate-display, extends FU-B22-pregate-display), as B23 did; paste both result lines. The clerk adds no FU-E1m-beat rows: the four rows FU-E1m-beat-base-occupied, FU-E1m-beat-fall-back, FU-E1m-beat-expansion-founded and FU-E1m-beat-weather-arrives are already on main in the ledger; cite those four hyphen names everywhere (the script's underscore names base_occupied, fallback, expansion, weather are replaced by them, in the clerk prompt, the E1m/E1n builder prompts and any list of row ids). The clerk takes the next free TD-VG-E number at landing time and says which. A ledger conflict on DRAFT-e1m-beat-text or DRAFT-e1n-marker: keep both sides when the copies are byte-identical to the ones on their branches (origin/push/vg-e1m, origin/push/vg-e1n); a differing copy is a STOP with the diff in the report, never a pick.`, { label: 'clerk:E-screens', phase: 'Clerk', schema: REPORT, agentType: 'engineer', model: 'sonnet' })
return { ...out, clerk, stacked: STACKED, baseRefs: BASE_REFS, next: 'Westley\'s verdict on the new story_reviews/E.md S-235 row (one word per row in the Dispatcher chat). The S-235 westley/ copy is HELD behind S-191 (g10). Stubs that remain (rows FU-E1m-beat-base-occupied, FU-E1m-beat-fall-back, FU-E1m-beat-expansion-founded, FU-E1m-beat-weather-arrives, already in the ledger): base occupied, fall back to an expansion, expansion founded and weather arrives (no sim source: E2/E-15 and a contract piece for the wave log); the economy marks of R-235-01/R-235-02 beyond strongpoints and the home base (P4/P6, E2). S-230, S-231, S-233 wait for an E2 spec; S-232 and S-234 are lane A. E1l, E1o, E1p-b stay held behind VG-P3.' }
